@'
import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_monaco/flutter_monaco.dart';

class MonacoEditorController {
  MonacoController? _ctrl;
  bool _ready = false;
  final List<Future<void> Function(MonacoController)> _pending = [];

  void _attach(MonacoController ctrl) {
    _ctrl = ctrl;
    _ready = true;
    for (final cmd in _pending) { cmd(ctrl); }
    _pending.clear();
  }

  void _enqueue(Future<void> Function(MonacoController) cmd) {
    if (_ready && _ctrl != null) { cmd(_ctrl!); } else { _pending.add(cmd); }
  }

  void setErrors(List<MonacoError> errors) {
    _enqueue((ctrl) async {
      final markers = errors.map((e) => MarkerData.error(
        range: Range(startLine: e.line, startColumn: e.col, endLine: e.line, endColumn: e.col + 1),
        message: e.message, source: 'PL/SQL Checker',
      )).toList();
      await ctrl.document.setMarkers(markers, owner: 'plsql-checker');
    });
  }

  void clearErrors() {
    _enqueue((ctrl) async { await ctrl.document.clearMarkers(owner: 'plsql-checker'); });
  }

  void setLanguage(String lang) {
    final ml = lang == 'javascript' ? MonacoLanguage.javascript : MonacoLanguage.sql;
    _enqueue((ctrl) async { await ctrl.document.setLanguage(ml); });
  }

  void dispose() { _ctrl?.dispose(); _ctrl = null; _ready = false; _pending.clear(); }
}

typedef MonacoController = MonacoEditorController;

class MonacoError {
  final int line;
  final int col;
  final String message;
  const MonacoError({required this.line, required this.col, required this.message});
}

class MonacoEditorWidget extends StatefulWidget {
  final MonacoEditorController controller;
  final String initialCode;
  final String language;
  final bool darkTheme;
  final ValueChanged<String>? onChanged;
  final void Function(int line, int col)? onCursorChanged;

  const MonacoEditorWidget({
    super.key,
    required this.controller,
    required this.initialCode,
    this.language = 'plsql',
    this.darkTheme = true,
    this.onChanged,
    this.onCursorChanged,
  });

  @override
  State<MonacoEditorWidget> createState() => _MonacoEditorWidgetState();
}

class _MonacoEditorWidgetState extends State<MonacoEditorWidget> {
  StreamSubscription<Range?>? _selectionSub;

  EditorOptions get _options => EditorOptions(
    language: widget.language == 'javascript' ? MonacoLanguage.javascript : MonacoLanguage.sql,
    theme: widget.darkTheme ? MonacoTheme.vsDark : MonacoTheme.vsLight,
    fontSize: 14,
    minimap: const MonacoMinimapOptions(enabled: true),
    wordWrap: MonacoWordWrap.off,
    lineNumbers: MonacoLineNumbers.on,
    renderWhitespace: RenderWhitespace.none,
    tabSize: 2,
  );

  void _onReady(MonacoController ctrl) {
    widget.controller._attach(ctrl);
    _selectionSub = ctrl.onSelectionChanged.listen((range) {
      if (range != null) widget.onCursorChanged?.call(range.startLine, range.startColumn);
    });
  }

  @override
  void didUpdateWidget(MonacoEditorWidget old) {
    super.didUpdateWidget(old);
    if (old.language != widget.language) widget.controller.setLanguage(widget.language);
  }

  @override
  void dispose() { _selectionSub?.cancel(); widget.controller.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return MonacoEditor(
      initialText: widget.initialCode,
      options: _options,
      contentDebounce: const Duration(milliseconds: 400),
      onReady: _onReady,
      onContentChanged: widget.onChanged,
    );
  }
}
